<script setup lang="ts">
import { ref } from 'vue'; import { NSelect, NButton, useMessage } from 'naive-ui'; import { useI18n } from 'vue-i18n'; import { useWorkspace } from '../demo/workspace'; import type { Scenario } from '../domain'; const { t } = useI18n(); const message = useMessage(); const { workspace, commands, persistenceIssue } = useWorkspace(); const scenario = ref<Scenario>(workspace.scenario); const scenarios: Scenario[] = ['normal', 'empty', 'error', 'stale', 'offline', 'partial'];
function reset() { commands.reset(scenario.value); message.success(t('common.resetDone')) }
</script><template><details class="demo-controls"><summary>{{ t('common.tools') }}</summary><p>{{ t('common.resetHint') }}</p><p v-if="persistenceIssue" role="alert">{{ t('common.storageError') }}</p><label for="demo-scenario">{{ t('common.scenario') }}</label><div class="actions"><NSelect id="demo-scenario" v-model:value="scenario" :aria-label="t('common.scenario')" :options="scenarios.map(s => ({ label: t(`scenarios.${s}`), value: s }))" style="width: 170px" /><NButton @click="reset">{{ t('common.reset') }}</NButton></div></details><p v-if="persistenceIssue" role="alert">{{ t('common.storageError') }}</p></template>
